static void pf_hsd_image_desc_copy(HSD_ImageDesc* idesc, u16 origx, u16 origy,
                              GXBool clear, bool sync, bool pixel_output)
{
    if (!idesc) {
        return;
    }

    GXSetTexCopySrc(origx, origy, idesc->width, idesc->height);
    GXSetTexCopyDst(idesc->width, idesc->height, idesc->format,
                    idesc->mipmap ? GX_TRUE : GX_FALSE);
    if (clear) {
        HSD_StateSetZMode(GX_TRUE, GX_LEQUAL, GX_TRUE);
    }
    if (pixel_output) {
        GXCopyTex(idesc->image_ptr, clear);
    }
    if (sync) {
        GXPixModeSync();
        GXInvalidateTexAll();
    }
}

void HSD_ImageDescCopyFromEFB(HSD_ImageDesc* idesc, u16 origx, u16 origy,
                              GXBool clear, bool sync)
{
    pf_hsd_image_desc_copy(idesc, origx, origy, clear, sync, true);
}

void pf_hsd_image_desc_copy_without_pixels(HSD_ImageDesc* idesc, u16 origx,
                                         u16 origy, GXBool clear, bool sync)
{
    pf_hsd_image_desc_copy(idesc, origx, origy, clear, sync, false);
}
